                if ch.tagName=='f': f=''.join(x.nodeValue or '' for x in ch.childNodes)
                if ch.tagName=='v': v=''.join(x.nodeValue or '' for x in ch.childNodes)
                if ch.tagName=='is': txt=''.join(x.nodeValue or '' for x in ch.getElementsByTagName('t'))
        cells.append((ref,s_,t,txt,f,v))
    print('ROW',r)
    for cell in cells:
        print('   ',cell)
